20	import { parsePercent } from '../../util/number';
21	import * as zrUtil from 'zrender/src/core/util';
22	import GlobalModel from '../../model/Global';
23	import ExtensionAPI from '../../core/ExtensionAPI';
24	import SunburstSeriesModel, { SunburstSeriesOption } from './SunburstSeries';
25	import { TreeNode } from '../../data/Tree';
26	
27	// let PI2 = Math.PI * 2;
28	const RADIAN = Math.PI / 180;
29	
30	export default function sunburstLayout(
31	    seriesType: 'sunburst',
32	    ecModel: GlobalModel,
33	    api: ExtensionAPI
34	) {
35	    ecModel.eachSeriesByType(seriesType, function (seriesModel: SunburstSeriesModel) {
36	        let center = seriesModel.get('center');
37	        let radius = seriesModel.get('radius');
38	
39	        if (!zrUtil.isArray(radius)) {
40	            radius = [0, radius];
41	        }
42	        if (!zrUtil.isArray(center)) {
43	            center = [center, center];
44	        }
45	
46	        const width = api.getWidth();
47	        const height = api.getHeight();
48	        const size = Math.min(width, height);
49	        const cx = parsePercent(center[0], width);
50	        const cy = parsePercent(center[1], height);
51	        const r0 = parsePercent(radius[0], size / 2);
52	        const r = parsePercent(radius[1], size / 2);
53	
54	        const startAngle = -seriesModel.get('startAngle') * RADIAN;
55	        const minAngle = seriesModel.get('minAngle') * RADIAN;
56	
57	        const virtualRoot = seriesModel.getData().tree.root;
58	        const treeRoot = seriesModel.getViewRoot();
59	        const rootDepth = treeRoot.depth;
60	
61	        const sort = seriesModel.get('sort');
62	        if (sort != null) {
63	            initChildren(treeRoot, sort);
64	        }
65	
66	        let validDataCount = 0;
67	        zrUtil.each(treeRoot.children, function (child) {
68	            !isNaN(child.getValue() as number) && validDataCount++;
69	        });
70	
71	        const sum = treeRoot.getValue() as number;
72	        // Sum may be 0
73	        const unitRadian = Math.PI / (sum || validDataCount) * 2;
74	
75	        const renderRollupNode = treeRoot.depth > 0;
76	        const levels = treeRoot.height - (renderRollupNode ? -1 : 1);
77	        const rPerLevel = (r - r0) / (levels || 1);
78	
79	        const clockwise = seriesModel.get('clockwise');
80	
81	        const stillShowZeroSum = seriesModel.get('stillShowZeroSum');
82	
83	        // In the case some sector angle is smaller than minAngle
84	        // let restAngle = PI2;
85	        // let valueSumLargerThanMinAngle = 0;
86	
87	        const dir = clockwise ? 1 : -1;
88	
89	        /**
90	         * Render a tree
91	         * @return increased angle
92	         */
93	        const renderNode = function (node: TreeNode, startAngle: number) {
94	            if (!node) {
95	                return;
96	            }
97	
98	            let endAngle = startAngle;
99	
100	            // Render self
101	            if (node !== virtualRoot) {
102	                // Tree node is virtual, so it doesn't need to be drawn
103	                const value = node.getValue() as number;
104	
105	                let angle = (sum === 0 && stillShowZeroSum)
106	                    ? unitRadian : (value * unitRadian);
107	                if (angle < minAngle) {
108	                    angle = minAngle;
109	                    // restAngle -= minAngle;
110	                }
111	                // else {
112	                //     valueSumLargerThanMinAngle += value;
113	                // }
114	
115	                endAngle = startAngle + dir * angle;
116	
117	                const depth = node.depth - rootDepth
118	                    - (renderRollupNode ? -1 : 1);
119	                let rStart = r0 + rPerLevel * depth;
120	                let rEnd = r0 + rPerLevel * (depth + 1);
121	
122	                const levelModel = seriesModel.getLevelModel(node);
123	                if (levelModel) {
124	                    let r0 = levelModel.get('r0', true);
125	                    let r = levelModel.get('r', true);
126	                    const radius = levelModel.get('radius', true);
127	
128	                    if (radius != null) {
129	                        r0 = radius[0];
130	                        r = radius[1];
131	                    }
132	
133	                    (r0 != null) && (rStart = parsePercent(r0, size / 2));
134	                    (r != null) && (rEnd = parsePercent(r, size / 2));
135	                }
136	
137	                node.setLayout({
138	                    angle: angle,
139	                    startAngle: startAngle,
140	                    endAngle: endAngle,
141	                    clockwise: clockwise,
142	                    cx: cx,
143	                    cy: cy,
144	                    r0: rStart,
145	                    r: rEnd
146	                });
147	            }
148	
149	            // Render children
150	            if (node.children && node.children.length) {
151	                // currentAngle = startAngle;
152	                let siblingAngle = 0;
153	                zrUtil.each(node.children, function (node) {
154	                    siblingAngle += renderNode(node, startAngle + siblingAngle);
155	                });
156	            }
157	
158	            return endAngle - startAngle;
159	        };
160	
161	        // Virtual root node for roll up
162	        if (renderRollupNode) {
163	            const rStart = r0;
164	            const rEnd = r0 + rPerLevel;
165	
166	            const angle = Math.PI * 2;
167	            virtualRoot.setLayout({
168	                angle: angle,
169	                startAngle: startAngle,
170	                endAngle: startAngle + angle,
171	                clockwise: clockwise,
172	                cx: cx,
173	                cy: cy,
174	                r0: rStart,
175	                r: rEnd
176	            });
177	        }
178	
179	        renderNode(treeRoot, startAngle);
180	    });
181	}
182	
183	/**
184	 * Init node children by order and update visual
185	 */
186	function initChildren(node: TreeNode, sortOrder?: SunburstSeriesOption['sort']) {
187	    const children = node.children || [];
188	
189	    node.children = sort(children, sortOrder);
190	
191	    // Init children recursively
192	    if (children.length) {
193	        zrUtil.each(node.children, function (child) {
194	            initChildren(child, sortOrder);
195	        });
196	    }
197	}
198	
199	/**
200	 * Sort children nodes
201	 *
202	 * @param {TreeNode[]}               children children of node to be sorted
203	 * @param {string | function | null} sort sort method
204	 *                                   See SunburstSeries.js for details.
205	 */
206	function sort(children: TreeNode[], sortOrder: SunburstSeriesOption['sort']) {
207	    if (zrUtil.isFunction(sortOrder)) {
208	        const sortTargets = zrUtil.map(children, (child, idx) => {
209	            const value = child.getValue() as number;
210	            return {
211	                params: {
212	                    depth: child.depth,
213	                    height: child.height,
214	                    dataIndex: child.dataIndex,
215	                    getValue: () => value
216	                },
217	                index: idx
218	            };
219	        });
220	        sortTargets.sort((a, b) => {
221	            return sortOrder(a.params, b.params);
222	        });
223	
224	        return zrUtil.map(sortTargets, (target) => {
225	            return children[target.index];
226	        });
227	    }
228	    else {
229	        const isAsc = sortOrder === 'asc';
230	        return children.sort(function (a, b) {
231	            const diff = ((a.getValue() as number) - (b.getValue() as number)) * (isAsc ? 1 : -1);
232	            return diff === 0
233	                ? (a.dataIndex - b.dataIndex) * (isAsc ? -1 : 1)
234	                : diff;
235	        });
236	    }
237	}
